UPDATE equipment_templates SET is_for_sale=0 WHERE category_id=9;
-- کشورهای قدیمی (ایجادشده قبل از این مهاجرت) هم سهم بستهٔ اولیه را دارند:
-- معافیت = جمع درآمد قالب‌های کاتالوگ داخل بستهٔ اولیهٔ فعال (idempotent؛ createNation جدید مقدار خودش را صریح می‌نویسد)
UPDATE nation_economy
   SET starter_factory_template_income = (
         SELECT COALESCE(SUM(t.income_per_cycle * ti.quantity), 0)
           FROM starter_templates st
           JOIN starter_template_items ti ON ti.starter_template_id = st.id
           JOIN equipment_templates t ON t.id = ti.equipment_template_id
           JOIN equipment_categories c ON c.id = t.category_id
          WHERE st.is_active = 1 AND c.key = 'factories'
       ),
       starter_mine_template_income = (
         SELECT COALESCE(SUM(t.income_per_cycle * ti.quantity), 0)
           FROM starter_templates st
           JOIN starter_template_items ti ON ti.starter_template_id = st.id
           JOIN equipment_templates t ON t.id = ti.equipment_template_id
           JOIN equipment_categories c ON c.id = t.category_id
          WHERE st.is_active = 1 AND c.key = 'mines'
       )
 WHERE starter_factory_template_income = 0 AND starter_mine_template_income = 0;
